-- contract: a nullable column with no default, its CHECK true for every null row, and the failure CHECK dropped and re-added with more allowed codes, so every row and insert the previous image makes still passes (data D6).
ALTER TABLE "builder"."model_account" ADD COLUMN "limit_reason" text;--> statement-breakpoint
ALTER TABLE "builder"."model_account" ADD CONSTRAINT "model_account_limit_reason" CHECK ("limit_reason" IN ('rate', 'credit'));--> statement-breakpoint
ALTER TABLE "notifications"."notification" DROP CONSTRAINT "notification_failed", ADD CONSTRAINT "notification_failed" CHECK ("kind" <> 'AUTOMATION_FAILED' or ("failure_code" is not null and "failure_code" in ('MODEL_NO_ACCOUNT', 'MODEL_ACCOUNTS_LIMITED', 'MODEL_ACCOUNTS_NO_CREDIT', 'MODEL_ACCOUNTS_REFUSED', 'MODEL_CALL_FAILED', 'MODEL_REFUSED', 'MODEL_ANSWER_CUT', 'MACHINE_UNAVAILABLE', 'MACHINE_LOST', 'HUB_UPDATED', 'INTERNAL_UNEXPECTED', 'DATABASE_UNAVAILABLE', 'INTERRUPTED', 'SCHEDULE_PUBLISH_FAILED')));